-- Synthetic end-to-end SQL fixture. All changes roll back; no real customer records.
do $t$
declare op uuid:=gen_random_uuid();a uuid:=gen_random_uuid();buyer uuid:=gen_random_uuid();so uuid:=gen_random_uuid();sa uuid:=gen_random_uuid();sb uuid:=gen_random_uuid();t uuid;other uuid;pr uuid;part uuid;sup uuid;batch uuid;buy uuid;cust uuid;rep uuid;inv uuid;claim uuid;ord uuid;sale uuid;tag text:=substr(replace(gen_random_uuid()::text,'-',''),1,12);v jsonb;funding uuid:=gen_random_uuid();tax_request uuid:=gen_random_uuid();output_request uuid:=gen_random_uuid();tax_payment uuid:=gen_random_uuid();return_id uuid;refund_id uuid;recovery_id uuid;recovery_request uuid:=gen_random_uuid();queue_count bigint;reward_request uuid;earned_sale uuid;reward_order uuid;line jsonb;today date:=(now() at time zone 'UTC')::date;
begin begin
insert into auth.users(id,email,email_confirmed_at) values(op,tag||'-op@example.invalid',now()),(a,tag||'-a@example.invalid',now()),(buyer,tag||'-buyer@example.invalid',now());
insert into auth.sessions(id,user_id,aal) values(so,op,'aal1'),(sa,a,'aal1'),(sb,buyer,'aal1');
insert into saas_private.operators(user_id,mfa_required) values(op,false);
set local role authenticated;
perform set_config('request.jwt.claims',jsonb_build_object('sub',op,'session_id',so,'aal','aal1','role','authenticated')::text,true);
t:=public.mt_admin_create_store('Integrated fixture','a-'||tag,'basic',a);other:=public.mt_admin_create_store('Other fixture','b-'||tag,'basic',buyer);perform public.saas_admin_manage(t,'trial',14);
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
perform public.mt_configure_sales(t,'USD');perform public.mt_configure_sales(t,'EUR');
perform public.mt_record_cash(t,funding,'funding','USD',30000,'Opening');
pr:=public.mt_add_product(t,'DEVICE','Device');part:=public.mt_add_product(t,'PART','Part');sup:=public.mt_add_supplier(t,gen_random_uuid(),'Supplier','');
batch:=public.mt_purchase_batch(t,gen_random_uuid(),sup,'USD','Invoice fixture',jsonb_build_array(jsonb_build_object('product_id',pr,'units',5,'unit_cost_minor',2000),jsonb_build_object('product_id',part,'units',4,'unit_cost_minor',1000)),14000);
if (select paid_minor from public.mt_list_purchase_batches(t) where id=batch) is distinct from 14000::bigint then raise exception 'Purchase allocation';end if;
select id into strict buy from public.mt_purchases where store_id=t and batch_id=batch and product_id=pr;
perform public.mt_set_currency_price(t,pr,'USD',5000);perform public.mt_set_currency_price(t,part,'USD',3000);
perform public.mt_storefront_enable(t,true);perform public.mt_storefront_list_product(t,pr,true);perform public.mt_delivery_enable(t,true);
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
ord:=public.mt_delivery_order('a-'||tag,gen_random_uuid(),'USD',jsonb_build_array(jsonb_build_object('product_id',pr,'units',2,'expected_price_minor',5000)),'Fixture address','000000000');
if exists(select 1 from public.mt_list_purchase_batches(t)) then raise exception 'Purchase leaked';end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
perform public.mt_dispatch_delivery(t,ord,'FIXTURE');sale:=public.mt_finish_order(t,ord,'fulfill');
if (select sum(line_total_minor) from public.mt_sale_receipt_lines(t,sale)) is distinct from 10000::numeric then raise exception 'Receipt mismatch';end if;
perform public.mt_record_return(t,gen_random_uuid(),sale,pr,1,'Customer return');
perform public.mt_supplier_return(t,gen_random_uuid(),buy,1,'Supplier return',true);
cust:=public.mt_add_customer(t,gen_random_uuid(),'Customer','');rep:=public.mt_add_repair(t,gen_random_uuid(),cust,'Device',null,'Fault');
perform public.mt_repair_transition(t,gen_random_uuid(),rep,'diagnosing','A');perform public.mt_repair_transition(t,gen_random_uuid(),rep,'repairing','B');perform public.mt_repair_transition(t,gen_random_uuid(),rep,'ready','C');
inv:=public.mt_repair_checkout(t,gen_random_uuid(),rep,'USD',2000,jsonb_build_array(jsonb_build_object('product_id',part,'units',1,'expected_price_minor',3000)),90);
claim:=public.mt_warranty_open(t,gen_random_uuid(),inv,'Warranty');perform public.mt_warranty_transition(t,gen_random_uuid(),claim,'accepted','Accepted');perform public.mt_warranty_part(t,gen_random_uuid(),claim,part,1,'Replacement');perform public.mt_warranty_transition(t,gen_random_uuid(),claim,'resolved','Resolved');perform public.mt_repair_refund(t,gen_random_uuid(),inv,1000,'Refund',true);
if (select quantity from public.mt_products where id=pr) is distinct from 3::bigint or (select quantity from public.mt_products where id=part) is distinct from 2::bigint then raise exception 'Stock mismatch';end if;
v:=public.mt_cash_reconciliation(t);if not exists(select 1 from jsonb_array_elements(v)x where x->>'currency'='USD' and x->>'recorded'='27000' and x->>'balanced'='true') then raise exception 'Cash mismatch %',v;end if;
v:=public.mt_operating_report(t,today,today);if not exists(select 1 from jsonb_array_elements(v)x where x->>'currency'='USD' and x->>'net_revenue'='9000' and x->>'cost'='4000' and x->>'gross_margin'='5000') then raise exception 'Profit mismatch %',v;end if;
v:=public.mt_trial_balance(t,today,today);if v->>'unknown_cost_events' is distinct from '0' or exists(select 1 from jsonb_array_elements(v->'rows')x group by x->>'currency' having sum((x->>'closing')::numeric)<>0) then raise exception 'Trial balance mismatch';end if;
v:=public.mt_management_statements(t,today,today,'USD');
if v->'translated'->>'cash' is distinct from '27000' or v->'translated'->>'result_before_tax' is distinct from '5000' or v->>'final_profit' is not null then raise exception 'Management statement mismatch %',v;end if;
perform public.mt_record_cash(t,gen_random_uuid(),'exchange','USD',1000,'Fixture FX','EUR',900);
v:=public.mt_management_statements(t,today,today,'USD');
if v->>'missing_rates' is distinct from '1' or v->>'translated' is not null then raise exception 'Missing FX not detected';end if;
perform public.mt_add_fx_rate(t,gen_random_uuid(),'EUR','USD',10,9,'Fixture');
v:=public.mt_management_statements(t,today,today,'USD');
if v->'translated'->>'cash' is distinct from '27000' or v->'translated'->>'result_before_tax' is distinct from '5000' then raise exception 'FX mismatch %',v;end if;
-- Source classifications, tax accrual idempotency and actual loyalty lifecycle.
perform public.mt_accounting_adjust(t,gen_random_uuid(),'funding_equity',funding,'USD',20000,'CAP-1','Capital evidence');
perform public.mt_accounting_adjust(t,gen_random_uuid(),'funding_loan',funding,'USD',10000,'LOAN-1','Loan evidence');
perform public.mt_accounting_adjust(t,tax_request,'income_tax_accrual',null,'USD',500,'TAX-1','Fixture assessed income tax');
perform public.mt_accounting_adjust(t,tax_request,'income_tax_accrual',null,'USD',500,'TAX-1','Fixture assessed income tax');
v:=public.mt_management_statements(t,today,today,'USD');
if v->'translated'->>'capital' is distinct from '20000' or v->'translated'->>'loan_payable' is distinct from '10000' or v->'translated'->>'income_tax' is distinct from '500' or v->'translated'->>'result_after_recorded_tax' is distinct from '4500' then raise exception 'Classified statement mismatch %',v;end if;
begin perform public.mt_accounting_adjust(t,gen_random_uuid(),'funding_equity',funding,'USD',1,'CAP-2','Excess');raise exception 'Excess classification accepted';exception when sqlstate '22023' then null;end;
-- Invoice-wide documented output tax, exact return reversal, payment and journal reconciliation.
select id into strict return_id from public.mt_returns where store_id=t and sale_id=sale;
select id into strict refund_id from public.mt_repair_refunds where store_id=t and invoice_id=inv;
v:=public.mt_indirect_tax_quote(t,'sale',sale,2500);
if v->>'tax_minor' is distinct from '2000' then raise exception 'Sale tax calculation';end if;
perform public.mt_record_indirect_tax(t,output_request,'sale',sale,2500,2000,'VAT-SALE','Synthetic rate');
perform public.mt_record_indirect_tax(t,output_request,'sale',sale,2500,2000,'VAT-SALE','Synthetic rate');
begin perform public.mt_record_indirect_tax(t,gen_random_uuid(),'sale',sale,2500,2000,'DUP','Duplicate');raise exception 'Duplicate tax accepted';exception when sqlstate '22023' then null;end;
begin perform public.mt_record_indirect_tax(t,gen_random_uuid(),'repair',inv,2500,999,'WRONG','Wrong amount');raise exception 'Wrong tax accepted';exception when sqlstate '22023' then null;end;
perform public.mt_record_indirect_tax(t,gen_random_uuid(),'repair',inv,2500,1000,'VAT-REPAIR','Synthetic rate');
perform public.mt_record_indirect_tax(t,gen_random_uuid(),'sale_return',return_id,null,1000,'VAT-RETURN','Original rate');
perform public.mt_record_indirect_tax(t,gen_random_uuid(),'repair_refund',refund_id,null,200,'VAT-REFUND','Original rate');
perform public.mt_record_cash(t,tax_payment,'expense','USD',300,'Fixture tax settlement');
perform public.mt_accounting_adjust(t,gen_random_uuid(),'expense_indirect_tax_payment',tax_payment,'USD',300,'VAT-PAY','Synthetic payment');
v:=public.mt_indirect_tax_summary(t);
if not exists(select 1 from jsonb_array_elements(v) x where x->>'currency'='USD' and x->>'assessed'='3000' and x->>'reversed'='1200' and x->>'paid'='300' and x->>'balance'='1500' and x->>'unclassified_documents'='0') then raise exception 'Tax settlement mismatch %',v;end if;
v:=public.mt_financial_reconciliation(t);
if v->>'balanced' is distinct from 'true' or not exists(select 1 from jsonb_array_elements(v->'rows') x where x->>'currency'='USD' and x->>'account'='indirect_tax_payable' and x->>'recorded'='-1500') then raise exception 'Reconciliation mismatch %',v;end if;
v:=public.mt_management_statements(t,today,today,'USD');
if v->'translated'->>'tax_payable' is distinct from '2000' or v->'translated'->>'result_after_recorded_tax' is distinct from '2700' or v->>'final_profit' is not null then raise exception 'After-tax management result mismatch %',v;end if;
begin perform public.mt_financial_reconciliation(other);raise exception 'Cross-tenant reconciliation accepted';exception when insufficient_privilege then null;end;
perform public.mt_set_loyalty(t,true,2,1000);
line:=jsonb_build_array(jsonb_build_object('product_id',pr,'units',1,'expected_price_minor',5000));
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
if public.mt_buyer_points('a-'||tag)->>'balance' is distinct from '1' then raise exception 'Initial points mismatch';end if;
ord:=public.mt_online_order('a-'||tag,gen_random_uuid(),'USD',line);
begin perform public.mt_admin_operations_overview(array[t]);raise exception 'Buyer accessed central monitoring';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
earned_sale:=public.mt_finish_order(t,ord,'fulfill');
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
if public.mt_buyer_points('a-'||tag)->>'balance' is distinct from '2' then raise exception 'Earned points mismatch';end if;
reward_request:=gen_random_uuid();reward_order:=public.mt_reward_order('a-'||tag,reward_request,'USD',line,2,1000,4500);
if public.mt_reward_order('a-'||tag,reward_request,'USD',line,2,1000,4500) is distinct from reward_order then raise exception 'Reward replay mismatch';end if;
if public.mt_buyer_points('a-'||tag)->>'balance' is distinct from '0' then raise exception 'Points not reserved';end if;
begin perform public.mt_reward_order('a-'||tag,gen_random_uuid(),'USD',line,2,1000,4500);raise exception 'Reward double spend';exception when sqlstate '22023' then null;end;
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
perform public.mt_finish_order(t,reward_order,'cancel');
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
if public.mt_buyer_points('a-'||tag)->>'balance' is distinct from '2' then raise exception 'Cancelled reward not released';end if;
reward_order:=public.mt_reward_order('a-'||tag,gen_random_uuid(),'USD',line,2,1000,4500);
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
sale:=public.mt_finish_order(t,reward_order,'fulfill');
if (select sum(line_total_minor) from public.mt_sale_receipt_lines(t,sale)) is distinct from 4500::numeric then raise exception 'Reward receipt mismatch';end if;
perform public.mt_record_return(t,gen_random_uuid(),earned_sale,pr,1,'Return earning order');
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
if public.mt_buyer_points('a-'||tag)->>'deficit' is distinct from '1' then raise exception 'Loyalty deficit mismatch';end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',op,'session_id',so,'aal','aal1','role','authenticated')::text,true);
v:=public.mt_admin_operations_overview(array[t,other]);
queue_count:=(v->'summary'->>'queued_recovery')::bigint;
recovery_id:=public.mt_admin_shared_recovery_request(recovery_request,'shared-001','tenant_export',t,null);
if public.mt_admin_shared_recovery_request(recovery_request,'shared-001','tenant_export',t,null) is distinct from recovery_id then raise exception 'Recovery replay mismatch';end if;
v:=public.mt_admin_operations_overview(array[t,other]);
if (v->'summary'->>'queued_recovery')::bigint<>queue_count+1 then raise exception 'Queue monitor mismatch';end if;
if not public.mt_admin_shared_recovery_cancel(recovery_id,'recovery') then raise exception 'Cancel recovery failed';end if;
v:=public.mt_admin_operations_overview(array[t,other]);
if (v->'summary'->>'queued_recovery')::bigint<>queue_count then raise exception 'Cancelled queue monitor mismatch';end if;
if v->>'live_billing_enabled' is distinct from 'false' or v->'summary'->>'paid' is distinct from '0' or not exists(select 1 from jsonb_array_elements(v->'stores') x where x->>'id'=t::text and x->>'licensed'='true' and x->>'storefront_active'='true') then raise exception 'Central monitoring mismatch %',v;end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',sb,'aal','aal1','role','authenticated')::text,true);
if exists(select 1 from public.mt_sale_receipt_lines(t,sale)) or exists(select 1 from public.mt_list_repair_refunds(t)) then raise exception 'Tenant leak';end if;
-- Design, original-image publication and domain authorization, without external services.
perform set_config('request.jwt.claims',jsonb_build_object('sub',op,'session_id',so,'aal','aal1','role','authenticated')::text,true);
v:=public.mt_design_change(t,0,0,'save',$theme${"brand":"Fixture shop","mark":"TS","tagline":"","mode":"dark","accent":"#60d5aa","background":"#0b1220","surface":"#121e31","text":"#edf3fb","font":"system","radius":"soft","density":"normal","layout":"cards","site":{"pages":[{"slug":"home","title":"Home","blocks":[{"type":"image","title":"Fixture","body":"","image":"hero","action":"none","tone":"surface","layout":{"desktop":6,"mobile":12,"align":"center","padding":"normal","image_fit":"wide","heading":"large"}}]}],"images":[{"id":"hero","alt":"Fixture image","data":"/9j/AAAA"}],"product_images":{},"desktop":{"layout":"cards","columns":3,"density":"normal"},"mobile":{"layout":"cards","columns":1,"density":"normal"}}}$theme$::jsonb);
if v->>'revision' is distinct from '1' then raise exception 'Design draft failed %',v;end if;
if public.mt_public_design('a-'||tag) is not null then raise exception 'Draft leaked';end if;
v:=public.mt_reserve_design_original(t,gen_random_uuid(),'hero','Fixture image');
if v->>'uploaded' is distinct from 'false' then raise exception 'Unexpected uploaded original';end if;
perform public.mt_design_change(t,1,0,'publish');
if public.mt_public_design('a-'||tag)#>>'{site,pages,0,blocks,0,layout,mobile}' is distinct from '12' then raise exception 'Published layout mismatch';end if;
begin perform public.mt_set_original_public(t,(v->>'id')::uuid,true);raise exception 'Unuploaded original allowed';exception when sqlstate '22023' then null;end;
if public.mt_public_originals('a-'||tag) is distinct from '[]'::jsonb then raise exception 'Unuploaded original leaked';end if;
v:=public.mt_domain_request(t,gen_random_uuid(),tag||'.example.com');
if v->>'state' is distinct from 'pending' or public.mt_resolve_domain(tag||'.example.com') is not null then raise exception 'Unverified domain resolved';end if;
if not public.mt_domain_disable(t,(v->>'id')::uuid) then raise exception 'Domain disable failed';end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sa,'aal','aal1','role','authenticated')::text,true);
begin perform public.mt_design_change(t,1,1,'publish');raise exception 'Owner accessed central design';exception when insufficient_privilege then null;end;
begin perform public.mt_domain_request(t,gen_random_uuid(),'another.example.com');raise exception 'Owner accessed central domains';exception when insufficient_privilege then null;end;
reset role;raise exception using errcode='ZX001',message='rollback';
exception when sqlstate 'ZX001' then raise notice 'Integrated commerce fixture passed; rolled back';end;end $t$;